    return name

def _save_jpeg(self, image: LTImage) -> str:
    """Save a JPEG encoded image"""
    raw_data = image.stream.get_rawdata()
    if raw_data is None:
        # If get_rawdata() returns None, try get_data() instead
        raw_data = image.stream.get_data()
        if not raw_data:
            raise PDFValueError("No image data found")

    name, path = self._create_unique_image_name(image, ".jpg")
    with open(path, "wb") as fp:
        if LITERAL_DEVICE_CMYK in image.colorspace:
            try:
                from PIL import Image, ImageChops  # type: ignore[import]
            except ImportError:
                raise ImportError(PIL_ERROR_MESSAGE)

            ifp = BytesIO(raw_data)
            i = Image.open(ifp)
            i = ImageChops.invert(i)
            i = i.convert("RGB")
            i.save(fp, "JPEG")
        else:
            fp.write(raw_data)

    return name
